tasks.solution:
fn shift_text(text: &str, shift: u8) -> String {
    let mut out = String::new();
    for c in text.chars() {
        if c.is_ascii_lowercase() {
            let moved = (c as u8 - b'a' + shift) % 26 + b'a';
            out.push(moved as char);
        } else {
            out.push(c);
        }
    }
    out
}

