use std::io;

#[derive(Debug)]
enum Status {
    Available,
    Borrowed(String),
    Lost,
}

#[derive(Debug)]
struct Book {
    id: u32,
    title: String,
    status: Status,
}

fn main() {
    let mut line = String::new();
    io::stdin().read_line(&mut line).unwrap();
    let mut words = line.split_whitespace();
    let status = match words.next() {
        Some("borrowed") => Status::Borrowed(words.next().unwrap_or("nobody").to_string()),
        Some("lost") => Status::Lost,
        _ => Status::Available,
    };
    let book = Book { id: 1, title: String::from("Dune"), status };
    println!("{:?}", book);
}

