fn checkout(state: &str, member: &str) -> Result<String, String> {
    if state == "available" {
        Ok(format!("{member} has it now"))
    } else if let Some(holder) = state.strip_prefix("borrowed ") {
        Err(format!("already borrowed by {holder}"))
    } else if state == "lost" {
        Err(String::from("lost"))
    } else {
        Err(String::from("no such book"))
    }
}

