fn parse_line(line: &str) -> Result<(String, u32), String> {
    let (name, score) = line.split_once(',').ok_or("missing comma")?;
    let score = score
        .trim()
        .parse::<u32>()
        .map_err(|e| format!("bad score for {}: {}", name.trim(), e))?;
    Ok((name.trim().to_string(), score))
}

