tasks.solution:
use std::io;

trait Summary {
    fn summarise(&self) -> String;
}

struct Entry {
    name: String,
    score: u32,
}

struct Group {
    name: String,
    scores: Vec<u32>,
}

impl Summary for Entry {
    fn summarise(&self) -> String {
        format!("{} scored {}", self.name, self.score)
    }
}

impl Summary for Group {
    fn summarise(&self) -> String {
        let total = self.scores.iter().sum::<u32>() as f64;
        let average = total / self.scores.len() as f64;
        format!("{}: {:.1} ({} scores)", self.name, average, self.scores.len())
    }
}

fn main() {
    let mut line = String::new();
    io::stdin().read_line(&mut line).unwrap();
    let mut words = line.split_whitespace();
    let name = words.next().unwrap_or("nobody").to_string();
    let scores: Vec<u32> = words.map(|w| w.parse().unwrap_or(0)).collect();
    let entry = Entry { name: name.clone(), score: scores[0] };
    let group = Group { name, scores };
    println!("{}", entry.summarise());
    println!("{}", group.summarise());
}

