    // Return the n largest items, largest first.
}

tasks.solution:
fn top_n<T: PartialOrd + Clone>(items: &[T], n: usize) -> Vec<T> {
    let mut v = items.to_vec();
    v.sort_by(|a, b| b.partial_cmp(a).unwrap());
    v.truncate(n);
    v
}

